"""SAGA orchestration with compensating transactions.

An orchestrator runs local transactions T1..T4 for an order. Each step commits
locally, so a failure cannot simply be rolled back: the orchestrator runs the
compensations of the already-committed steps in reverse order.
"""
state = {"orders": {}, "stock": {"book": 3}, "wallet": {"alice": 500}, "shipments": []}

def create_order(ctx):   state["orders"][ctx["id"]] = "CREATED"
def cancel_order(ctx):   state["orders"][ctx["id"]] = "CANCELLED"
def take_payment(ctx):
    if state["wallet"][ctx["user"]] < ctx["price"]: raise RuntimeError("insufficient funds")
    state["wallet"][ctx["user"]] -= ctx["price"]
def refund_payment(ctx): state["wallet"][ctx["user"]] += ctx["price"]
def reserve_stock(ctx):
    if state["stock"][ctx["item"]] < 1: raise RuntimeError("out of stock")
    state["stock"][ctx["item"]] -= 1
def release_stock(ctx):  state["stock"][ctx["item"]] += 1
def ship(ctx):
    if ctx.get("courier_down"): raise RuntimeError("courier API unavailable")
    state["shipments"].append(ctx["id"])

SAGA = [("T1 create order", create_order, cancel_order),
        ("T2 process payment", take_payment, refund_payment),
        ("T3 update inventory", reserve_stock, release_stock),
        ("T4 deliver order", ship, None)]

def run_saga(ctx):
    done = []
    for name, step, comp in SAGA:
        try:
            step(ctx); done.append((name, comp)); print(f"   {name}: committed")
        except RuntimeError as e:
            print(f"   {name}: FAILED ({e}) -> compensating in reverse")
            for n, c in reversed(done):
                if c: c(ctx); print(f"   compensate {n.split()[0].replace('T','C')} ({c.__name__})")
            return "ROLLED BACK"
    state["orders"][ctx["id"]] = "COMPLETED"; return "COMPLETED"

for ctx in [dict(id="o1", user="alice", item="book", price=200),
            dict(id="o2", user="alice", item="book", price=200, courier_down=True),
            dict(id="o3", user="alice", item="book", price=400)]:
    print(f"order {ctx['id']}:")
    print("  ->", run_saga(ctx), "| wallet", state["wallet"]["alice"], "| stock", state["stock"]["book"])
print("final orders:", state["orders"], "shipments:", state["shipments"])
